namespace ChestCounter;

/// <summary>Small 32x32 alpha masks (one byte per pixel) of the icons shown beside the captions of the "cards" overlay.
/// They are tinted and blended with the card color by <see cref="Render"/>, so no image resource is needed.</summary>
internal static class OverlayIcons
{
    public const int Size = 32;

    private static readonly Dictionary<string, byte[]> Masks = new()
    {
        ["trophy"] = Convert.FromBase64String(""),
        ["x"] = Convert.FromBase64String(""),
        ["pct"] = Convert.FromBase64String(""),
        ["pad"] = Convert.FromBase64String(""),
        ["cross"] = Convert.FromBase64String(""),
        ["kpm"] = Convert.FromBase64String(""),
        ["skull"] = Convert.FromBase64String(""),
        ["clock"] = Convert.FromBase64String(""),
        ["hourglass"] = Convert.FromBase64String(""),
        ["bolt"] = Convert.FromBase64String(""),
        ["assist"] = Convert.FromBase64String(""),
        ["target"] = Convert.FromBase64String(""),
        ["chest"] = Convert.FromBase64String(""),
    };

    /// <summary>The mask of an icon name (see <see cref="OverlayCell.Icon"/>), or null when there is none.</summary>
    public static byte[]? For(string? icon) => icon != null && Masks.TryGetValue(icon, out var m) ? m : null;

    /// <summary>Square <paramref name="size"/> pixels of 32-bit BGRA (opaque): the icon in <c>fg</c> blended over the flat
    /// color <c>bg</c>, rows bottom-up as GDI expects for a positive-height DIB.</summary>
    public static int[] Render(byte[] mask, int size, (int R, int G, int B) fg, (int R, int G, int B) bg)
    {
        var px = new int[size * size];
        for (var y = 0; y < size; y++)
        {
            for (var x = 0; x < size; x++)
            {
                // Bilinear sample of the mask at the centre of the destination pixel.
                var sx = (x + 0.5) * Size / size - 0.5;
                var sy = (y + 0.5) * Size / size - 0.5;
                var x0 = (int)Math.Floor(sx);
                var y0 = (int)Math.Floor(sy);
                var fx = sx - x0;
                var fy = sy - y0;
                double At(int ix, int iy) => mask[Math.Clamp(iy, 0, Size - 1) * Size + Math.Clamp(ix, 0, Size - 1)] / 255.0;
                var a = At(x0, y0) * (1 - fx) * (1 - fy) + At(x0 + 1, y0) * fx * (1 - fy)
                      + At(x0, y0 + 1) * (1 - fx) * fy + At(x0 + 1, y0 + 1) * fx * fy;
                var r = (int)Math.Round(bg.R + (fg.R - bg.R) * a);
                var g = (int)Math.Round(bg.G + (fg.G - bg.G) * a);
                var b = (int)Math.Round(bg.B + (fg.B - bg.B) * a);
                px[(size - 1 - y) * size + x] = (r << 16) | (g << 8) | b;
            }
        }
        return px;
    }
}
